'use strict';
// PERSONALIZA AQUÍ: copia memory-1.jpg ... memory-6.jpg a assets/images/memories/
// y cambia los valores src correspondientes. Si falta una foto, se usa fallback.
const MEMORIES = [
  {src:'assets/images/sunflower-field.webp',fallback:'assets/images/sunflower-field.webp',caption:'Donde siempre sale el sol',alt:'Un campo de girasoles al atardecer'},
  {src:'assets/images/yellow-tulips.webp',fallback:'assets/images/yellow-tulips.webp',caption:'Pequeñas cosas, mucho cariño',alt:'Tulipanes amarillos sobre una mesa clara'},
  {src:'assets/images/yellow-bouquet.webp',fallback:'assets/images/yellow-bouquet.webp',caption:'La luz que traes a mis días',alt:'Un ramo amarillo junto a una ventana'},
  {src:'assets/images/pressed-flowers.webp',fallback:'assets/images/pressed-flowers.webp',caption:'Lo bonito merece quedarse',alt:'Flores prensadas conservadas en papel artesanal'},
  {src:'assets/images/sunset-flowers.webp',fallback:'assets/images/sunset-flowers.webp',caption:'Un atardecer pendiente contigo',alt:'Girasoles bajo un cielo cálido'},
  {src:'assets/images/close-sunflower.webp',fallback:'assets/images/close-sunflower.webp',caption:'Y entre todas las flores, tú',alt:'Los pétalos dorados de un girasol'}
];
// Cambia por 'assets/audio/music.mp3' cuando agregues tu canción.
const MUSIC_SOURCE = 'assets/audio/ambient.wav';
const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
const finePointer = matchMedia('(hover: hover) and (pointer: fine)');
const $ = (selector,root=document) => root.querySelector(selector);
const $$ = (selector,root=document) => [...root.querySelectorAll(selector)];
const delay = ms => new Promise(resolve => setTimeout(resolve,reducedMotion.matches?0:ms));
let toastTimer,gardenTimer;
const music = new Audio(MUSIC_SOURCE); music.loop=true; music.volume=.16; music.preload='none';
function soundState(playing){$('#sound-toggle').setAttribute('aria-pressed',String(playing));$('#sound-toggle').setAttribute('aria-label',playing?'Silenciar música':'Activar música');}
function toast(message){clearTimeout(toastTimer);$('#sound-status').textContent=message;$('#sound-status').classList.add('visible');toastTimer=setTimeout(()=>$('#sound-status').classList.remove('visible'),4200);}
async function playMusic(){try{await music.play();soundState(true);}catch{soundState(false);toast('La música no pudo empezar. Puedes intentarlo con el botón de sonido.');}}
$('#sound-toggle').addEventListener('click',()=>{if(music.paused)playMusic();else{music.pause();soundState(false);}});
music.addEventListener('error',()=>{soundState(false);toast('La música no está disponible. Las flores siguen aquí para ti.');});
const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');revealObserver.unobserve(entry.target);}}),{threshold:.13});
function observeReveals(){$$('.reveal').forEach(el=>revealObserver.observe(el));}
const sceneObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{entry.target.classList.toggle('in-view',entry.isIntersecting);if(entry.isIntersecting){$$('.chapter-nav a').forEach(link=>{const active=link.hash==='#'+entry.target.id;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');});if(entry.target.id==='jardin')entry.target.classList.add('grown');if(entry.target.id==='distancia')entry.target.classList.add('distance-revealed');}}),{threshold:.28});
$$('.scene').forEach(el=>sceneObserver.observe(el));
$('#open-gift').addEventListener('click',async()=>{$('#open-gift').disabled=true;playMusic();$('.intro').classList.add('leaving');await delay(1050);$('.intro').hidden=true;$('#experience').hidden=false;document.body.classList.add('gift-opened');window.scrollTo({top:0,behavior:'instant'});$('#flowers-title').focus({preventScroll:true});observeReveals();});
$('.monogram').addEventListener('click',event=>{event.preventDefault();if(!$('#experience').hidden){$('#experience').hidden=true;$('.intro').hidden=false;$('.intro').classList.remove('leaving');$('#open-gift').disabled=false;document.body.classList.remove('gift-opened');window.scrollTo({top:0,behavior:'instant'});$('#open-gift').focus({preventScroll:true});}});

// Ramo: capas botánicas con profundidad suave y sin dependencias externas.
const blooms=[[196,163,.78,-23],[401,161,.72,20],[262,122,.87,-8],[342,103,.72,15],[139,226,.7,-33],[440,229,.72,35],[225,219,.95,-8],[357,215,.96,10],[293,279,.88,2]];
$('#bouquet').innerHTML=`<g class="bouquet-stems">${blooms.map(([x,y])=>`<path d="M298 492Q${(x+300)/2} 350 ${x} ${y}" fill="none" stroke="#7c8256" stroke-width="3"/>`).join('')}</g><g class="bouquet-leaves">${[[201,310,-20,1.8],[380,301,85,1.9],[263,356,-15,1.5],[330,381,80,1.5],[157,275,-17,1.5],[414,281,90,1.4]].map(([x,y,r,s])=>`<use href="#leaf" transform="translate(${x} ${y}) rotate(${r}) scale(${s})"/>`).join('')}</g>${blooms.map(([x,y,s,r],i)=>`<g class="bouquet-bloom" data-depth="${i%3+1}" style="--sway-delay:-${i*.7}s"><g transform="translate(${x} ${y}) rotate(${r}) scale(${s})"><use href="#bloom"/></g></g>`).join('')}<g fill="none" stroke="#c5a479" stroke-width="3"><path d="M283 426Q306 419 319 429M301 428Q242 386 250 415T306 432Q356 384 353 419T305 431M303 431Q285 453 267 455M309 434Q330 453 340 460"/></g>`;
function installTilt(element,amount,callback){let frame=0;element.addEventListener('pointermove',event=>{if(!finePointer.matches||reducedMotion.matches)return;const rect=element.getBoundingClientRect(),x=(event.clientX-rect.left)/rect.width-.5,y=(event.clientY-rect.top)/rect.height-.5;cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{element.style.setProperty('--rx',`${-y*amount}deg`);element.style.setProperty('--ry',`${x*amount}deg`);callback?.(x,y);});});element.addEventListener('pointerleave',()=>{cancelAnimationFrame(frame);element.style.setProperty('--rx','0deg');element.style.setProperty('--ry','0deg');callback?.(0,0);});}
installTilt($('.bouquet-stage'),10,(x,y)=>{$$('.bouquet-bloom').forEach(el=>{const depth=Number(el.dataset.depth);el.style.transform=`translate(${x*depth*7}px,${y*depth*5}px)`;});});
const postcards=[
  ['Por tu sonrisa','Porque incluso estando lejos, tienes esa forma tan tuya de hacer que mis días se sientan un poquito más bonitos.','UN POQUITO DE TI, EN MIS DÍAS'],
  ['Por nosotros','Porque aunque haya kilómetros entre los dos, seguimos encontrando maneras de sentirnos cerca.','SIEMPRE EN EL MISMO LADO'],
  ['Por ti','Porque no necesito una fecha para recordarte lo especial que eres para mí.','HOY, Y TODOS LOS DÍAS']
];
const cardFlowers=[`<use href="#bloom" transform="translate(75 59) scale(.75)"/>`,`<use href="#bloom" transform="translate(57 55) scale(.5)"/><use href="#bloom" transform="translate(99 80) scale(.4)"/>`,`<g transform="translate(75 59)"><path d="M0 22C-44 16-42-15-25-29L-6-16 0-37 12-15 30-26C44 6 27 27 0 22Z" fill="url(#petal-gold)"/><path d="M0 20Q-13 0-6-16M0 20Q18 0 12-15" fill="none" stroke="#c19a39" stroke-width=".8"/></g>`];
postcards.forEach(([title,message,foot],i)=>{const card=document.createElement('button');card.className='postcard reveal';card.setAttribute('aria-pressed','false');card.setAttribute('aria-label',`Abrir postal: ${title}`);card.innerHTML=`<span class="card-inner"><span class="card-face card-front"><span class="card-number">${['I','II','III'][i]}</span><svg viewBox="0 0 150 170" aria-hidden="true"><path d="M75 152Q64 103 75 61" fill="none" stroke="#7b8051" stroke-width="1.6"/><use href="#leaf" transform="translate(71 128) scale(.65)"/>${cardFlowers[i]}</svg><span class="card-title">${title}</span><span class="card-hint">TOCA PARA DESCUBRIR ↗</span></span><span class="card-face card-back" aria-hidden="true"><span class="mini-flower">✳</span><span class="card-title">${title}</span><span class="card-message">${message}</span><span class="card-hint">${foot}</span></span></span>`;$('#cards-grid').append(card);installTilt(card,7);card.addEventListener('click',()=>{const flipped=card.getAttribute('aria-pressed')!=='true';card.setAttribute('aria-pressed',String(flipped));card.setAttribute('aria-label',`${flipped?'Cerrar':'Abrir'} postal: ${title}`);$('.card-front',card).setAttribute('aria-hidden',String(flipped));$('.card-back',card).setAttribute('aria-hidden',String(!flipped));});});

// Diálogos nativos: foco contenido, cierre con Escape y retorno del foco.
function openDialog(dialog){dialog.showModal();document.body.classList.add('modal-open');}
$$('dialog').forEach(dialog=>{$('.close-dialog',dialog).addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>{if(!$('dialog[open]'))document.body.classList.remove('modal-open');});});
MEMORIES.forEach((memory,index)=>{const button=document.createElement('button');button.className='memory reveal';button.style.setProperty('--rotation',['-3deg','2deg','-2deg','3deg','-2deg','2deg'][index]);button.setAttribute('aria-label',`Abrir foto ${index+1}: ${memory.caption}`);const image=new Image();image.src=memory.src;image.alt=memory.alt;image.loading='lazy';image.decoding='async';image.width=500;image.height=600;image.addEventListener('error',()=>{if(!image.src.endsWith(memory.fallback))image.src=memory.fallback;});const caption=document.createElement('span');caption.textContent=memory.caption;button.append(image,caption);$('#memory-gallery').append(button);button.addEventListener('click',()=>{$('#modal-photo').src=image.currentSrc||image.src;$('#modal-photo').alt=memory.alt;$('#modal-caption').textContent=memory.caption;openDialog($('#photo-dialog'));});});
$('#open-letter').addEventListener('click',async()=>{const button=$('#open-letter');button.disabled=true;button.classList.add('opened');await delay(1050);openDialog($('#letter-dialog'));$('#letter-dialog').scrollTop=0;button.disabled=false;});
$('#letter-dialog').addEventListener('close',()=>{$('#open-letter').classList.remove('opened');$('#jardin').scrollIntoView({behavior:reducedMotion.matches?'instant':'smooth'});$('#garden-heading').setAttribute('tabindex','-1');$('#garden-heading').focus({preventScroll:true});});
$('#close-letter').addEventListener('click',()=>$('#letter-dialog').close());
const reasons=['Por tus ocurrencias','Por tu forma de querer','Por las noches hablando contigo','Por hacerme sonreír','Por cada llamada','Por los momentos que todavía nos faltan vivir','Porque eres tú','Por las tonterías que solo nosotros entendemos','Por todo lo bonito que viene'];
reasons.forEach((reason,index)=>{const button=document.createElement('button');button.className='garden-flower';button.style.setProperty('--height',`${[225,305,250,340,275,325,235,310,255][index]}px`);button.style.setProperty('--grow-delay',`${index*.16}s`);button.style.setProperty('--lean',`${[-9,5,-5,4,-3,7,-6,3,10][index]}deg`);button.setAttribute('aria-label',`Descubrir razón ${index+1}`);button.innerHTML=`<svg viewBox="0 0 120 340" aria-hidden="true"><g class="growing-stem"><path d="M60 337Q47 219 60 66" fill="none" stroke="#7c855d" stroke-width="2.5"/></g><g class="growing-leaf"><use href="#leaf" transform="translate(55 233) scale(1)"/><use href="#leaf" transform="translate(53 270) rotate(95) scale(.9)"/></g><g class="growing-bloom"><use href="#bloom" transform="translate(60 64) scale(.86) rotate(${index*13})"/></g></svg>`;button.addEventListener('click',()=>{clearTimeout(gardenTimer);$$('.garden-flower').forEach(el=>el.classList.remove('picked'));button.classList.add('picked');$('#garden-message').textContent=reason;$('#garden-message').classList.add('visible');gardenTimer=setTimeout(()=>{$('#garden-message').classList.remove('visible');button.classList.remove('picked');},4500);});$('#garden').append(button);});
for(let i=0;i<14;i++){const light=document.createElement('i');light.style.setProperty('--x',`${8+(i*37)%85}%`);light.style.setProperty('--y',`${8+(i*19)%85}%`);light.style.setProperty('--delay',`${i*.37}s`);$('.final-lights').append(light);}
$('#open-surprise').addEventListener('click',()=>openDialog($('#surprise-dialog')));
$('.final-return').addEventListener('click',()=>{$('#surprise-dialog').close();$('.final-footer').scrollIntoView({behavior:reducedMotion.matches?'instant':'smooth'});});
// El cursor nativo sigue visible; solo se añade un pequeño detalle junto a él.
const cursor=$('.cursor-flower');
document.addEventListener('pointermove',event=>{if(!finePointer.matches||reducedMotion.matches)return;cursor.style.transform=`translate(${event.clientX+13}px,${event.clientY+8}px)`;cursor.style.opacity=event.target.closest('button,a')?'.75':'0';});
document.addEventListener('pointerout',event=>{if(!event.relatedTarget)cursor.style.opacity='0';});
document.addEventListener('visibilitychange',()=>document.body.classList.toggle('tab-away',document.hidden));
